60	 * How the work at this node stands: still going, landed, or dropped.
61	 *
62	 * ## Why not `open | closed | merged`
63	 *
64	 * That was the shape for a long time, and it was GitHub's response fields rather
65	 * than this project's vocabulary. It split where the world does not and merged
66	 * where the world does:
67	 *
68	 *   - `closed` covered both an issue finished and an issue dropped, which are
69	 *     opposite outcomes. GitHub itself distinguishes them — `stateReason` — and
70	 *     nothing here read it.
71	 *   - `merged` and `closed` were separate, though every reader asked only whether
72	 *     the node was open. Measured before the change: two readers, both
73	 *     `state === "open"`, and `merged` was produced and never distinguished from
74	 *     `closed` anywhere.
75	 *
76	 * So the enum said three things and meant two, while the thing it could not say
77	 * was the one a person cares about.
78	 *
79	 * ## Why `merged` is not a fourth value
80	 *
81	 * Because `kind` already carries it. A pull request that landed is a merged pull
82	 * request; an issue that landed was closed as completed. One outcome, spelled per
83	 * kind by the reader that knows which spelling GitHub uses. Keeping both would be
84	 * the same redundancy in the other direction.
85	 *
86	 * `open` stays `open`. It is GitHub's word and it is also the word a person says
87	 * about an issue, which is the test this project applies to a borrowed name.
88	 */
89	export type NodeState =
90	  /** Work can still happen here. */
91	  | "open"
92	  /** It landed: a merged pull request, or an issue closed as completed. */
93	  | "done"
94	  /** It was dropped: closed as not planned or duplicate, or a pull request closed unmerged. */
95	  | "abandoned";
96	
97	export interface WorkNode {
98	  number: number;
99	  kind: NodeKind;
100	  state: NodeState;
101	  /** What this node is under. Absent at a root, whatever the wire spelling was. */
102	  parent?: number;
103	  /** A turn is in flight here: something is working on this node and nothing else may. */
104	  running: boolean;
105	}
106	
107	/** How deep a chain this will walk before deciding it has found a cycle. */
108	export const MAX_DEPTH = 10;
109	
110	/**
111	 * `root` and everything under it, nearest first.
112	 *
113	 * Breadth-first so the order reads the way the work was built: the node the person
114	 * named, then its children, then theirs. A node whose parent is not in `nodes` is
115	 * simply not reached — this answers over what it was given rather than asking for
116	 * more, which is what keeps it pure.
117	 *
118	 * Depth-capped and visit-marked. A cycle cannot be written through the tools, but it
119	 * can be written by hand into an issue body, and an unbounded walk over one is a job
120	 * that never ends.
121	 */
122	export function subtree(nodes: readonly WorkNode[], root: number): WorkNode[] {
123	  const byParent = new Map<number, WorkNode[]>();
124	  const byNumber = new Map<number, WorkNode>();
125	  for (const node of nodes) {
126	    byNumber.set(node.number, node);
127	    if (node.parent === undefined) continue;
128	    const siblings = byParent.get(node.parent) ?? [];
129	    siblings.push(node);
130	    byParent.set(node.parent, siblings);
131	  }
132	
133	  const start = byNumber.get(root);
134	  if (!start) return [];
135	
136	  const found: WorkNode[] = [start];
137	  const seen = new Set<number>([root]);
138	  let frontier = [root];
139	  for (let depth = 0; depth < MAX_DEPTH && frontier.length > 0; depth += 1) {
140	    const next: number[] = [];
141	    for (const parent of frontier) {
142	      for (const child of byParent.get(parent) ?? []) {
143	        if (seen.has(child.number)) continue;
144	        seen.add(child.number);
145	        found.push(child);
146	        next.push(child.number);
147	      }
148	    }
149	    frontier = next;
150	  }
151	  return found;
152	}
