157	 * Deliberately not filtered by state. An agent can close the issue it is working on
158	 * and keep going — that is how a run finishes — so a closed node can still be holding
159	 * a run, and it is exactly the one a person wants stopped.
160	 */
161	export function nodesToStop(nodes: readonly WorkNode[]): WorkNode[] {
162	  return nodes.filter((node) => node.running);
